	text := "Go tili 2009-yilda e'lon qilindi. Hozir 1.27 versiyasi bor!"
	words := strings.Fields(text)
	digits, letters := 0, 0
	for _, r := range text {
		switch {
		case unicode.IsDigit(r):
			digits++
		case unicode.IsLetter(r):
			letters++
		}
