import "fmt"

func caesar(s string, shift int) string {
	out := []rune(s)
	for i, c := range out {
		switch {
		case c >= 'a' && c <= 'z':
			out[i] = 'a' + (c-'a'+rune(shift)+26)%26
		case c >= 'A' && c <= 'Z':
			out[i] = 'A' + (c-'A'+rune(shift)+26)%26
		}
	}
	return string(out)
}

func main() {
	fmt.Println('z'-'a', 'a'+1, string(rune('a'+1)))

	secret := caesar("Salom Go", 3)
	fmt.Println(secret)
	fmt.Println(caesar(secret, -3))
}

