import "fmt"

func digitSum(n int) int {
	sum := 0
	for n > 0 {
		sum += n % 10 // oxirgi raqam
		n /= 10       // uni tashlash
	}
	return sum
}

func reverse(n int) int {
	r := 0
	for n > 0 {
		r = r*10 + n%10
		n /= 10
	}
	return r
}

func main() {
	fmt.Println(digitSum(1234), digitSum(999))
	fmt.Println(reverse(1234), reverse(1200))
	fmt.Println(1234%100, 1234/100) // oxirgi ikki raqam va qolgani
}

